def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "mop_area": And([
            self.water_dispensing,  # Water is being dispensed
            self.flooring_is_tile,  # Floor is tile
            self.setting_is_indoor_facility  # Indoor facility setting
        ]),  # Mopping with continuous water dispensing on tile floor creates slippery hazard
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
